/// reorderable-list: Drag or keyboard
private struct ReorderableListExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var stages: [(id: String, name: String, count: Int)] = [
        (id: "new", name: "New", count: 12),
        (id: "contacted", name: "Contacted", count: 8),
        (id: "proposal", name: "Proposal sent", count: 5),
        (id: "negotiation", name: "Negotiation", count: 3),
    ]

    private func row(_ stage: (id: String, name: String, count: Int)) -> some View {
        HStack(spacing: theme.spacing.space3) {
            MonarchDragHandle("Reorder " + stage.name, onMove: { move(stage.id, $0) })
                .draggable(stage.id)
            Text(stage.name).monarchTextStyle(.body)
            Spacer()
            MonarchBadge("\(stage.count)")
        }
        .padding(theme.spacing.space3)
        .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: theme.radius.md, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: theme.radius.md, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: 1))
        .dropDestination(for: String.self) { ids, _ in
            guard let id = ids.first, let from = stages.firstIndex(where: { $0.id == id }),
                let to = stages.firstIndex(where: { $0.id == stage.id })
            else { return false }
            stages.move(fromOffsets: IndexSet(integer: from), toOffset: to > from ? to + 1 : to)
            return true
        }
    }

    private func move(_ id: String, _ direction: MonarchDragHandleDirection) {
        guard let from = stages.firstIndex(where: { $0.id == id }) else { return }
        let to = direction == .up ? from - 1 : from + 2
        guard (0...stages.count).contains(to), direction == .up ? from > 0 : from < stages.count - 1 else { return }
        stages.move(fromOffsets: IndexSet(integer: from), toOffset: to)
    }

    var body: some View {
        VStack(spacing: theme.spacing.space1) {
            ForEach(stages, id: \.id) { stage in
                row(stage)
            }
        }
    }
}

